head.b:skin:
/* =============================================
   CSS Custom Properties
   ============================================= */
:root {
  --color-primary:     #0094d2;
  --color-primary-dk:  #0077aa;
  --color-dark:        #1a1a2e;
  --color-mid:         #333333;
  --color-text:        #444444;
  --color-muted:       #888888;
  --color-border:      #e8e8e8;
  --color-bg:          #f4f6f8;
  --color-white:       #ffffff;
  --color-card-hover:  #fafcff;

  --font-heading: 'Oswald', sans-serif;
  --font-body:    'Inter', sans-serif;

  --radius:   6px;
  --radius-lg: 12px;
  --shadow-sm: 0 1px 4px rgba(0,0,0,.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10);
  --shadow-lg: 0 8px 32px rgba(0,0,0,.13);

  --transition: 0.22s ease;
  --content-width: 1060px;
  --sidebar-width: 340px;
}

/* =============================================
   Reset & Base
   ============================================= */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.7;
  color: var(--color-text);
  background: var(--color-bg);
}

a { color: var(--color-primary); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--color-primary-dk); text-decoration: underline; }

img { max-width: 100%; height: auto; display: block; }

h1,h2,h3,h4,h5,h6 {
  font-family: var(--font-heading);
  font-weight: 500;
  line-height: 1.3;
  color: var(--color-dark);
}

/* =============================================
   Layout Shell
   ============================================= */
.content-outer {
  max-width: var(--content-width);
  margin: 0 auto;
  background: var(--color-white);
  box-shadow: var(--shadow-lg);
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
}

.content-inner { padding: 0; }

/* =============================================
   Navbar (hide Blogger default)
   ============================================= */
.Navbar { display: none !important; }

/* =============================================
   Header
   ============================================= */
.header-outer {
  background: linear-gradient(135deg, var(--color-dark) 0%, #16213e 100%);
  padding: 28px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.Header h1.title {
  font-family: var(--font-heading);
  font-size: clamp(26px, 4vw, 42px);
  font-weight: 600;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin: 0;
  text-shadow: none;
}

.Header h1.title a,
.Header h1 { color: var(--color-white); }

.Header .description {
  font-family: var(--font-body);
  font-size: 13px;
  color: rgba(255,255,255,0.55);
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-top: 6px;
}

#header, body#layout #header {
  flex: 1;
}

#header-right, body#layout #header-right {
  flex-shrink: 0;
}

#header-right .widget { margin: 0; }

/* Search form in header-right */
.searchform {
  display: flex;
  gap: 0;
}

.searchform input[type="text"],
.s {
  font-family: var(--font-body);
  font-size: 14px;
  padding: 9px 14px;
  border: none;
  border-radius: var(--radius) 0 0 var(--radius);
  background: rgba(255,255,255,0.12);
  color: var(--color-white);
  width: 200px;
  outline: none;
  transition: background var(--transition);
}

.searchform input[type="text"]::placeholder,
.s::placeholder { color: rgba(255,255,255,0.45); }
.searchform input[type="text"]:focus,
.s:focus { background: rgba(255,255,255,0.22); }

input[type="submit"],
input[type="button"] {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 600;
  padding: 9px 16px;
  background: var(--color-primary);
  border: none;
  border-radius: 0 var(--radius) var(--radius) 0;
  color: var(--color-white);
  cursor: pointer;
  transition: background var(--transition);
}

input[type="submit"]:hover,
input[type="button"]:hover { background: var(--color-primary-dk); }

/* =============================================
   Navigation Menu
   ============================================= */
#cssmenu {
  background: var(--color-mid);
  position: sticky;
  top: 0;
  z-index: 1000;
  box-shadow: 0 2px 8px rgba(0,0,0,.25);
}

#cssmenu ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 0;
  background: transparent;
  border: none;
  box-shadow: none;
}

#cssmenu ul li { position: relative; }

#cssmenu ul li a {
  display: block;
  padding: 15px 22px;
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.5px;
  color: rgba(255,255,255,0.88);
  text-decoration: none;
  text-transform: uppercase;
  transition: color var(--transition), background var(--transition);
  white-space: nowrap;
}

#cssmenu ul li a:hover,
#cssmenu ul li.active > a {
  color: var(--color-primary);
  background: rgba(255,255,255,0.06);
  text-decoration: none;
}

/* Dropdown */
#cssmenu ul li ul {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  min-width: 200px;
  background: #2a2a2a;
  border-top: 2px solid var(--color-primary);
  border-radius: 0 0 var(--radius) var(--radius);
  box-shadow: var(--shadow-md);
  flex-direction: column;
}

#cssmenu ul li:hover > ul { display: flex; }

#cssmenu ul li ul li a {
  padding: 11px 18px;
  font-size: 13px;
  color: rgba(255,255,255,0.75);
  border-bottom: 1px solid rgba(255,255,255,0.07);
}

#cssmenu ul li ul li:last-child a { border-bottom: none; }

/* Third-level */
#cssmenu ul li ul li ul {
  top: 0;
  left: 100%;
  border-top: none;
  border-left: 2px solid var(--color-primary);
  border-radius: 0 var(--radius) var(--radius) 0;
}

/* Mobile hamburger toggle */
#nav-toggle {
  display: none;
  padding: 14px 20px;
  cursor: pointer;
  background: none;
  border: none;
  color: var(--color-white);
  font-size: 22px;
  line-height: 1;
}

/* =============================================
   Main layout (sidebar + content)
   ============================================= */
.main-outer { background: var(--color-white); }

.region-inner.main-inner {
  display: flex;
  gap: 0;
  align-items: flex-start;
  padding: 0;
}

.column-center-outer { flex: 1; min-width: 0; }
.column-center-inner {
  padding: 28px 28px 28px 28px;
  border-right: 1px solid var(--color-border);
}

.column-right-outer { width: var(--sidebar-width); flex-shrink: 0; }
.column-right-inner { padding: 28px 22px; }

.column-left-outer { display: none; }

/* =============================================
   Blog Posts
   ============================================= */
.date-header { display: none; }

.post-outer {
  margin-bottom: 32px;
  padding-bottom: 32px;
  border-bottom: 1px solid var(--color-border);
}

.post-outer:last-child { border-bottom: none; margin-bottom: 0; padding-bottom: 0; }

.post {
  background: var(--color-white);
  border-radius: var(--radius);
  transition: box-shadow var(--transition), transform var(--transition);
}

.post:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

h2.post-title {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 500;
  line-height: 1.35;
  margin: 0 0 10px;
}

h2.post-title a {
  color: var(--color-dark);
  transition: color var(--transition);
}

h2.post-title a:hover {
  color: var(--color-primary);
  text-decoration: none;
}

.post-header {
  margin-bottom: 10px;
  font-size: 12px;
  color: var(--color-muted);
  display: flex;
  gap: 14px;
  align-items: center;
  flex-wrap: wrap;
}

.post-body {
  font-size: 15px;
  line-height: 1.75;
  color: var(--color-text);
}

.post-body img {
  border-radius: var(--radius);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  padding: 0;
  background: transparent;
  margin: 16px 0;
}

.post-body .tr-caption-container {
  background: #f8f8f8;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 8px;
  font-size: 13px;
  color: var(--color-muted);
}

/* Read more link */
.rmlink {
  display: block;
  margin-top: 14px;
  text-align: right;
}

.rmlink a {
  display: inline-block;
  padding: 7px 18px;
  background: var(--color-primary);
  color: var(--color-white) !important;
  border-radius: var(--radius);
  font-size: 13px;
  font-weight: 600;
  text-decoration: none !important;
  transition: background var(--transition), transform var(--transition);
}

.rmlink a:hover {
  background: var(--color-primary-dk);
  transform: translateX(2px);
}

/* Post footer (visible on single post) */
.post-footer {
  display: none;
  margin-top: 20px;
  padding: 10px 14px;
  background: #f8f9fa;
  border-radius: var(--radius);
  font-size: 12px;
  color: var(--color-muted);
  border: 1px solid var(--color-border);
}

.post-footer-line { margin-bottom: 4px; }
.post-footer-line:last-child { margin-bottom: 0; }

/* Labels */
.Label a {
  display: inline-block;
  padding: 3px 12px;
  background: #eef7fb;
  color: var(--color-primary) !important;
  font-size: 12px;
  font-weight: 600;
  border-radius: 20px;
  margin: 3px 3px 3px 0;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: background var(--transition), color var(--transition);
  text-decoration: none !important;
  border: none !important;
  float: none !important;
  height: auto !important;
  line-height: normal !important;
}

.Label a:hover {
  background: var(--color-primary);
  color: var(--color-white) !important;
}

/* =============================================
   Pagination
   ============================================= */
#blog-pager, .pagenavi {
  text-align: center;
  padding: 24px 0 8px;
  clear: both;
}

#blog-pager a,
.pagenavi span,
.pagenavi a {
  display: inline-block;
  margin: 3px;
  padding: 7px 15px;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  color: var(--color-mid) !important;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  transition: all var(--transition);
}

#blog-pager a:hover,
.pagenavi a:hover {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-white) !important;
  text-decoration: none;
}

.pagenavi .current {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-white) !important;
}

/* =============================================
   Sidebar
   ============================================= */
.sidebar h2 {
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--color-dark);
  padding-bottom: 10px;
  margin-bottom: 14px;
  border-bottom: 2px solid var(--color-primary);
}

.sidebar .widget {
  margin-bottom: 30px;
  padding-bottom: 28px;
  border-bottom: 1px solid var(--color-border);
}

.sidebar .widget:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.sidebar .widget-content {
  font-size: 14px;
  line-height: 1.6;
}

.sidebar .widget ul { list-style: none; padding: 0; }
.sidebar .widget ul li {
  padding: 6px 0;
  border-bottom: 1px solid var(--color-border);
  font-size: 14px;
}
.sidebar .widget ul li:last-child { border-bottom: none; }

/* =============================================
   Comments
   ============================================= */
.comments { margin-top: 36px; }

.comments h4,
.cmess {
  font-family: var(--font-heading);
  font-size: 20px;
  font-weight: 500;
  color: var(--color-dark);
  margin-bottom: 20px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--color-border);
}

#comments .comment-author {
  padding: 18px 0;
  border-top: 1px solid var(--color-border);
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

#comments .comment-author:first-child { border-top: none; padding-top: 0; }

.avatar-image-container {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid var(--color-border);
}

.avatar-image-container img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  background: transparent !important;
  margin: 0 !important;
}

.comment-block { flex: 1; min-width: 0; }

.comment-header {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 5px;
}

.comment-header a { color: var(--color-dark); }

.comment-body {
  font-size: 14px;
  line-height: 1.65;
  background: #f8f9fa;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 12px 16px;
}

.comment-timestamp {
  font-size: 12px;
  color: var(--color-muted);
  margin-top: 6px;
  display: block;
}

.comment-timestamp a { color: var(--color-muted); }
.datetime { display: none; }
.icon.blog-author { display: none !important; }

/* Comment form */
.comment-form { margin-top: 28px; }

#comment-post-message,
.comment-form h4 {
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 500;
  margin-bottom: 14px;
  color: var(--color-dark);
}

.blogger-iframe-colorize {
  border-radius: var(--radius);
  border: 1px solid var(--color-border) !important;
}

/* =============================================
   Tabs / PageList
   ============================================= */
.tabs-inner .widget ul {
  background: transparent;
  border: none;
  box-shadow: none;
  margin: 0;
}

.tabs-inner .widget li a {
  padding: 8px 16px;
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 500;
  color: var(--color-mid);
  border: none;
}

.tabs-inner .widget li.selected a,
.tabs-inner .widget li a:hover {
  color: var(--color-primary);
  background: #eef7fb;
  border-radius: var(--radius);
}

/* =============================================
   Footer
   ============================================= */
.footer-outer {
  background: var(--color-dark);
  border-top: 3px solid var(--color-primary);
  padding: 32px;
  text-align: center;
}

.footer-outer .widget-content,
.footer-outer .Attribution {
  color: rgba(255,255,255,0.55);
  font-size: 13px;
}

.footer-outer a {
  color: rgba(255,255,255,0.75);
  transition: color var(--transition);
}

.footer-outer a:hover { color: var(--color-primary); text-decoration: none; }

/* =============================================
   Responsive
   ============================================= */
@media (max-width: 860px) {
  .region-inner.main-inner { flex-direction: column; }
  .column-right-outer { width: 100%; }
  .column-center-inner { border-right: none; border-bottom: 1px solid var(--color-border); }
  .column-center-inner, .column-right-inner { padding: 20px 16px; }

  #nav-toggle { display: block; }
  #cssmenu ul { display: none; flex-direction: column; }
  #cssmenu ul.open { display: flex; }
  #cssmenu ul li ul { position: static; border-left: 3px solid var(--color-primary); border-top: none; border-radius: 0; box-shadow: none; min-width: 0; }
  #cssmenu ul li:hover > ul { display: none; }
  #cssmenu ul li ul.open { display: flex; }

  .header-outer { flex-direction: column; align-items: flex-start; padding: 20px; }
  .searchform input[type="text"], .s { width: 140px; }
}

@media (max-width: 480px) {
  h2.post-title { font-size: 18px; }
  .column-center-inner, .column-right-inner { padding: 14px 12px; }
}

/* =============================================
   Blog pager misc
   ============================================= */
#blog-pager-older-link, #blog-pager-newer-link { float: none; }
.blog-mobile-link { margin-top: 8px; }

/* =============================================
   Body faux-columns (Blogger structural divs — hide decorative relics)
   ============================================= */
.body-fauxcolumns, .content-fauxcolumns,
.fauxcolumn-outer, .fauxborder-left, .fauxborder-right,
.fauxcolumn-inner, .cap-top, .cap-bottom,
.cap-left, .cap-right,
.main-cap-top, .main-cap-bottom,
.header-cap-top, .header-cap-bottom,
.footer-cap-top, .footer-cap-bottom,
.tabs-cap-top, .tabs-cap-bottom,
.content-cap-top, .content-cap-bottom,
.content-fauxborder-left, .content-fauxborder-right,
.header-fauxborder-left, .header-fauxborder-right,
.main-fauxborder-left, .main-fauxborder-right,
.footer-fauxborder-left, .footer-fauxborder-right,
.tabs-fauxborder-left, .tabs-fauxborder-right { display: none !important; }

/* =============================================
   Post-footer visible on item pages (override the hide-all above)
   ============================================= */
.item-page .post-footer { display: block; }

head.b:template-skin:




body { min-width: 320px; }
.content-outer, .content-fauxcolumn-outer, .region-inner {
  min-width: 0; max-width: $(content.width); _width: $(content.width);
}
.main-inner .columns { padding-left: 0; padding-right: $(main.column.right.width); }
.main-inner .fauxcolumn-center-outer { left: 0; right: $(main.column.right.width); }
.main-inner .fauxcolumn-left-outer  { width: 0; }
.main-inner .fauxcolumn-right-outer { width: $(main.column.right.width); }
.main-inner .column-left-outer  { width: 0; right: 100%; margin-left: 0; }
.main-inner .column-right-outer { width: $(main.column.right.width); margin-right: -$(main.column.right.width); }
#layout { min-width: 0; }
#layout .content-outer { min-width: 0; width: 800px; }
#layout .region-inner  { min-width: 0; width: auto; }

head.script:
var thumbnail_mode = 'no-float';
var summary_noimg  = 420;
var summary_img    = 320;
var img_thumb_height = 180;
var img_thumb_width  = 180;

b:includable.script:
                          (function() {
                            var items  = ;
                            var msgs   = ;
                            var config = ;
// 
                            var cursor = null;
                            if (items && items.length > 0) {
                              cursor = parseInt(items[items.length - 1].timestamp) + 1;
                            }
                            var bodyFromEntry = function(entry) {
                              if (entry.gd$extendedProperty) {
                                for (var k in entry.gd$extendedProperty) {
                                  if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
                                    return '<span class="deleted-comment">' + entry.content.$t + '</span>';
                                  }
                                }
                              }
                              return entry.content.$t;
                            };
                            var parse = function(data) {
                              cursor = null;
                              var comments = [];
                              if (data && data.feed && data.feed.entry) {
                                for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
                                  var comment = {};
                                  var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
                                  comment.id = id ? id[2] : null;
                                  comment.body = bodyFromEntry(entry);
                                  comment.timestamp = Date.parse(entry.published.$t) + '';
                                  if (entry.author && entry.author.constructor === Array) {
                                    var auth = entry.author[0];
                                    if (auth) {
                                      comment.author = {
                                        name: (auth.name ? auth.name.$t : undefined),
                                        profileUrl: (auth.uri ? auth.uri.$t : undefined),
                                        avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                                      };
                                    }
                                  }
                                  if (entry.link) {
                                    if (entry.link[2]) { comment.link = comment.permalink = entry.link[2].href; }
                                    if (entry.link[3]) {
                                      var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                                      if (pid && pid[1]) { comment.parentId = pid[1]; }
                                    }
                                  }
                                  comment.deleteclass = 'item-control blog-admin';
                                  if (entry.gd$extendedProperty) {
                                    for (var k in entry.gd$extendedProperty) {
                                      if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                                        comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                                      } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                                        comment.displayTime = entry.gd$extendedProperty[k].value;
                                      }
                                    }
                                  }
                                  comments.push(comment);
                                }
                              }
                              return comments;
                            };
                            var paginator = function(callback) {
                              if (hasMore()) {
                                var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
                                if (cursor) { url += '&published-min=' + new Date(cursor).toISOString(); }
                                window.bloggercomments = function(data) {
                                  var parsed = parse(data);
                                  cursor = parsed.length < 50 ? null : parseInt(parsed[parsed.length - 1].timestamp) + 1;
                                  callback(parsed);
                                  window.bloggercomments = null;
                                };
                                url += '&callback=bloggercomments';
                                var script = document.createElement('script');
                                script.type = 'text/javascript';
                                script.src = url;
                                document.getElementsByTagName('head')[0].appendChild(script);
                              }
                            };
                            var hasMore = function() { return !!cursor; };
                            var getMeta = function(key, comment) {
                              if ('iswriter' == key) {
                                return (!!comment.author && comment.author.name == config.authorName && comment.author.profileUrl == config.authorUrl) ? 'true' : '';
                              } else if ('deletelink' == key) {
                                return config.baseUri + '/delete-comment.g?blogID=' + config.blogId + '&postID=' + comment.id;
                              } else if ('deleteclass' == key) {
                                return comment.deleteclass;
                              }
                              return '';
                            };
                            var replybox = null, replyUrlParts = null, replyParent = undefined;
                            var onReply = function(commentId, domId) {
                              if (replybox == null) {
                                replybox = document.getElementById('comment-editor');
                                if (replybox != null) { replybox.height = '250px'; replybox.style.display = 'block'; replyUrlParts = replybox.src.split('#'); }
                              }
                              if (replybox && (commentId !== replyParent)) {
                                document.getElementById(domId).insertBefore(replybox, null);
                                replybox.src = replyUrlParts[0] + (commentId ? '&parentID=' + commentId : '') + '#' + replyUrlParts[1];
                                replyParent = commentId;
                              }
                            };
                            var hash = (window.location.hash || '#').substring(1);
                            var startThread, targetComment;
                            if (/^comment-form_/.test(hash)) { startThread = hash.substring('comment-form_'.length); }
                            else if (/^c[0-9]+$/.test(hash)) { targetComment = hash.substring(1); }
                            var configJso = { 'maxDepth': config.maxThreadDepth };
                            var provider = {
                              'id': config.postId, 'data': items, 'loadNext': paginator, 'hasMore': hasMore,
                              'getMeta': getMeta, 'onReply': onReply, 'rendered': true,
                              'initComment': targetComment, 'initReplyThread': startThread,
                              'config': configJso, 'messages': msgs
                            };
                            var render = function() {
                              if (window.goog && window.goog.comments) {
                                window.goog.comments.render(document.getElementById('comment-holder'), provider);
                              }
                            };
                            if (window.goog && window.goog.comments) { render(); }
                            else {
                              window.goog = window.goog || {};
                              window.goog.comments = window.goog.comments || {};
                              window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
                              window.goog.comments.loadQueue.push(render);
                            }
// 
                          })();

body.script:
//
var thumbnail_mode = thumbnail_mode || 'no-float';
var summary_noimg  = summary_noimg  || 430;
var summary_img    = summary_img    || 340;
var img_thumb_height = img_thumb_height || 180;
var img_thumb_width  = img_thumb_width  || 180;

function createSummaryAndThumb(pID) {
  var div = document.getElementById(pID);
  if (!div) return;
  var imgtag = '';
  var img = div.getElementsByTagName('img');
  var summ = summary_noimg;

  if (img.length >= 1) {
    var src = img[0].getAttribute('src');
    if (src) {
      imgtag = '<span style="float:left;margin:0 12px 8px 0"><img src="' + src +
        '" width="' + img_thumb_width + '" height="' + img_thumb_height +
        '" style="border-radius:4px;object-fit:cover;" /></span>';
      summ = summary_img;
    }
  }

  var text = div.textContent || div.innerText || '';
  text = text.trim();
  if (text.length > summ) {
    text = text.substring(0, summ - 1) + '&hellip;';
  }
  div.innerHTML = imgtag + '<p>' + text + '</p>';
}
//

//
(function() {
  var toggle = document.getElementById('nav-toggle');
  var list   = document.getElementById('nav-list');
  if (toggle && list) {
    toggle.addEventListener('click', function() {
      list.classList.toggle('open');
    });
  }

  // Replace defunct Blogger default avatars with a modern placeholder SVG data URI
  var defaultAvatars = [
    'http://img1.blogblog.com/img/anon36.png',
    'https://img1.blogblog.com/img/anon36.png',
    'http://img2.blogblog.com/img/b36-rounded.png',
    'https://img2.blogblog.com/img/b36-rounded.png'
  ];
  var placeholder = 'data:image/svg+xml,%3Csvg xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22 width%3D%2244%22 height%3D%2244%22 viewBox%3D%220 0 44 44%22%3E%3Ccircle cx%3D%2222%22 cy%3D%2222%22 r%3D%2222%22 fill%3D%22%23e0e0e0%22%2F%3E%3Ccircle cx%3D%2222%22 cy%3D%2218%22 r%3D%228%22 fill%3D%22%23bbb%22%2F%3E%3Cellipse cx%3D%2222%22 cy%3D%2238%22 rx%3D%2213%22 ry%3D%228%22 fill%3D%22%23bbb%22%2F%3E%3C%2Fsvg%3E';

  document.querySelectorAll('img').forEach(function(img) {
    if (defaultAvatars.indexOf(img.getAttribute('src')) !== -1) {
      img.setAttribute('src', placeholder);
    }
  });
})();
